<?php
namespace App\Domain\Library\Services; use App\Models\{College,LibraryFine,LibraryTransaction,User}; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class LibraryFineService { public function assess(College $college,LibraryTransaction $tx,User $actor,float $rate):LibraryFine {return DB::transaction(function()use($college,$tx,$actor,$rate){$tx=LibraryTransaction::lockForUpdate()->findOrFail($tx->id);$end=$tx->returned_on??now()->toDateString();$days=max(0,$tx->due_on->diffInDays($end)); if($days<1) throw ValidationException::withMessages(['transaction'=>'No overdue days to assess.']); $start=$tx->due_on->copy()->addDay(); return LibraryFine::firstOrCreate(['college_id'=>$college->id,'library_transaction_id'=>$tx->id,'type'=>LibraryFine::TYPE_OVERDUE,'period_start'=>$start,'period_end'=>$end],['library_member_id'=>$tx->library_member_id,'days_overdue'=>$days,'rate_per_day'=>number_format($rate,2,'.',''),'assessed_amount'=>number_format($days*$rate,2,'.',''),'status'=>LibraryFine::STATUS_ASSESSED,'assessed_by'=>$actor->id,'assessed_at'=>now(),'created_by'=>$actor->id]);});} public function pay(LibraryFine $fine,User $actor,string $reference=''):LibraryFine{return DB::transaction(function()use($fine,$actor,$reference){$f=LibraryFine::lockForUpdate()->findOrFail($fine->id); if($f->status===LibraryFine::STATUS_PAID) throw ValidationException::withMessages(['fine'=>'Fine is already paid.']);$f->update(['paid_amount'=>$f->assessed_amount,'status'=>LibraryFine::STATUS_PAID,'paid_by'=>$actor->id,'paid_at'=>now(),'payment_reference'=>$reference,'updated_by'=>$actor->id]);return $f;});}}
